cat > tests/forms_test.sh <<'EOF'
#!/bin/bash
fail=0
. lib/actions.sh
bash bin/render event | grep -q 'action=' || { echo "render"; fail=1; }
# legacy form stays accepted (compat)
bash bin/handle POST '/events/1/edit?/save' | grep -q '^200 save' || { echo "handle legacy"; fail=1; }
# Cirrus function URL only allows [A-Za-z0-9_.-] in query keys (docs/platform/cirrus-functions.md)
for a in save publish assign refund; do
  key=$(action_url "$a"); key=${key#\?}; key=${key%%=*}
  [[ "$key" =~ ^[A-Za-z0-9_.-]+$ ]] || { echo "action_url key not allowed: $key"; fail=1; }
done
for p in 'events/1/edit save' 'events/1/edit publish' 'events/1/seats assign' 'orders/5012/refund refund'; do
  set -- $p
  [ "$(bash bin/handle POST "/$1?_action=$2")" = "200 $2" ] || { echo "handle new $2"; fail=1; }
done
[ "$(bash bin/handle POST '/events/1/edit?_action=nope')" = "404" ] || { echo "unknown action"; fail=1; }
[ "$(bash bin/handle GET '/events/1/edit?_action=save')" = "404" ] || { echo "GET must 404"; fail=1; }
bash bin/render event | grep -q 'action="?_action=save"' || { echo "render new url"; fail=1; }
exit $fail
EOF
bash tests/forms_test.sh; echo exit=$?

cat > lib/actions.sh <<'EOF'
#!/bin/bash
# Form actions: a form posts to its own page with the action named in the query (?_action=name).
# The key must stay within [A-Za-z0-9_.-]: the Cirrus function URL rejects other characters (EVT-412).
action_url() { echo "?_action=$1"; }
# Prints the action named by a query string, or nothing. The legacy form ?/name is still accepted.
action_from_query() { case "$1" in _action=*) echo "${1#_action=}" ;; /*) echo "${1#/}" ;; esac; }
EOF
sed -i 's|^- フォームは自分のページに POST する。.*|- フォームは自分のページに POST する。どの操作かはクエリで指定する: `?_action=<操作名>`（lib/actions.sh の action_url）。旧形式 `?/<操作名>` も受理する。クエリのキーに `/` を使わない理由: Cirrus の function URL は `A-Za-z0-9_.-` 以外のキーを 400 で拒否する（EVT-412）|' docs/framework.md
bash tests/forms_test.sh; echo exit=$?; git diff --stat; grep -rn 'action_url\|action_from_query' --exclude-dir=.git . | grep -v '^./notes\|^./tests'
